::databricks_core::open_enum! {
    /// The status of the model version. Valid values are: * `PENDING_REGISTRATION`:
    /// Request to register a new model version is pending as server performs
    /// background tasks.
    ///
    /// * `FAILED_REGISTRATION`: Request to register a new model version has failed.
    ///
    /// * `READY`: Model version is ready for use.
    pub enum ModelVersionStatus {
        /// Request to register a new model version has failed.
        FailedRegistration => "FAILED_REGISTRATION",
        /// Request to register a new model version is pending as server performs
        /// background tasks.
        PendingRegistration => "PENDING_REGISTRATION",
        /// Model version is ready for use.
        Ready => "READY",
    }
}

