/// The Forecasting API allows you to create and get serverless forecasting
/// experiments
#[derive(Debug, Clone)]
pub struct ForecastingApi {
    api: ApiClient,
}

impl ForecastingApi {
    /// Wrap an [`ApiClient`].
    #[must_use]
    pub fn new(api: ApiClient) -> Self {
        Self { api }
    }

    /// Creates a serverless forecasting experiment. Returns the experiment ID.
    ///
    /// `POST /api/2.0/automl/create-forecasting-experiment`
    pub async fn create_experiment(
        &self,
        request: CreateForecastingExperimentRequest,
    ) -> ::databricks_core::Result<
        WaitGetExperimentForecastingSucceeded<CreateForecastingExperimentResponse>,
    > {
        let path = String::from("/api/2.0/automl/create-forecasting-experiment");
        let mut call = Call::new(Method::POST, path).workspace();
        call = call.json(&request)?;
        let response = self
            .api
            .send::<CreateForecastingExperimentResponse>(call)
            .await?;
        let param = response.experiment_id.clone().unwrap_or_default();
        Ok(WaitGetExperimentForecastingSucceeded {
            api: Clone::clone(self),
            experiment_id: param,
            response,
            timeout: ::std::time::Duration::from_secs(7200),
            on_progress: None,
        })
    }

    /// Public RPC to get forecasting experiment
    ///
    /// `GET /api/2.0/automl/get-forecasting-experiment/{experiment_id}`
    pub async fn get_experiment(
        &self,
        request: GetForecastingExperimentRequest,
    ) -> ::databricks_core::Result<ForecastingExperiment> {
        let path = format!(
            "/api/2.0/automl/get-forecasting-experiment/{}",
            path_param(&request.experiment_id.to_string(), false)
        );
        let call = Call::new(Method::GET, path).workspace();
        self.api.send::<ForecastingExperiment>(call).await
    }

    /// Repeatedly calls [`get_experiment`](Self::get_experiment) until the result reaches SUCCEEDED.
    pub async fn wait_get_experiment_forecasting_succeeded(
        &self,
        experiment_id: impl Into<String>,
        timeout: ::std::time::Duration,
        on_progress: Option<wait::Progress<ForecastingExperiment>>,
    ) -> ::databricks_core::Result<ForecastingExperiment> {
        let param: String = experiment_id.into();
        let callback = ::std::sync::Mutex::new(on_progress);
        let callback = &callback;
        wait::poll(timeout, || {
            let fut = self.get_experiment(
                GetForecastingExperimentRequest::default().with_experiment_id(param.clone()),
            );
            async move {
                let value = fut.await?;
                if let Some(cb) = callback
                    .lock()
                    .unwrap_or_else(::std::sync::PoisonError::into_inner)
                    .as_mut()
                {
                    cb(&value);
                }
                wait::check_state(
                    value,
                    wait::States {
                        status_path: &["state"],
                        message_path: &[],
                        targets: &["SUCCEEDED"],
                        failures: &["FAILED", "CANCELLED"],
                    },
                )
            }
        })
        .await
    }
}

/// Returned by operations that start a long-running change; waits until
/// the result reaches SUCCEEDED.
pub struct WaitGetExperimentForecastingSucceeded<R> {
    api: ForecastingApi,
    /// The ID being waited on.
    pub experiment_id: String,
    /// The operation's immediate response.
    pub response: R,
    timeout: ::std::time::Duration,
    on_progress: Option<wait::Progress<ForecastingExperiment>>,
}

impl<R: ::std::fmt::Debug> ::std::fmt::Debug for WaitGetExperimentForecastingSucceeded<R> {
    fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
        f.debug_struct("WaitGetExperimentForecastingSucceeded")
            .field("experiment_id", &self.experiment_id)
            .field("response", &self.response)
            .field("timeout", &self.timeout)
            .finish_non_exhaustive()
    }
}

impl<R> WaitGetExperimentForecastingSucceeded<R> {
    /// Override the default timeout.
    #[must_use]
    pub fn timeout(mut self, timeout: ::std::time::Duration) -> Self {
        self.timeout = timeout;
        self
    }

    /// Called with the polled value on every poll.
    #[must_use]
    pub fn on_progress(mut self, f: impl FnMut(&ForecastingExperiment) + Send + 'static) -> Self {
        self.on_progress = Some(Box::new(f));
        self
    }

    /// Wait until the result reaches SUCCEEDED.
    pub async fn wait(self) -> ::databricks_core::Result<ForecastingExperiment> {
        self.api
            .wait_get_experiment_forecasting_succeeded(
                self.experiment_id,
                self.timeout,
                self.on_progress,
            )
            .await
    }
}

